/**
 * @param {number[]} nums
 * @return {number}
 */
var minimumCost = function(nums) {
    const n = nums.length;
    let min = Infinity;

    for (let i = 1; i < n - 1; i++) {
        for (let j = i + 1; j < n; j++) {
            min = Math.min(min, nums[0] + nums[i] + nums[j]);
        }
    }

    return min;
};

/**
 * @param {number[]} nums
 * @return {number}
 */
var minimumCost = function(nums) {
    const copy = nums.slice(1).sort((a, b) => a - b);

    return nums[0] + copy[0] + copy[1];
};

/**
 * @param {number[]} nums
 * @return {number}
 */
var minimumCost = function(nums) {
    let min1 = Infinity;
    let min2 = Infinity;

    for (let i = 1; i < nums.length; i++) {
        if (nums[i] <= min1) {
            min2 = min1;
            min1 = nums[i];
        } else if (nums[i] < min2) {
            min2 = nums[i];
        }
    }

    return nums[0] + min1 + min2;
};
